import gurobipy as gp
from gurobipy import GRB
capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
if not capacity_records:
    raise ValueError('No capacity record found.')
resource_capacity = int(capacity_records[0]['values']['resource_capacity'])
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
if not product_records:
    raise ValueError('No product records found.')
item_names = []
item_value = {}
resource_requirement = {}
for rec in product_records:
    name = rec['values']['item_name']
    item_names.append(name)
    try:
        item_value[name] = int(rec['values']['item_value'])
        resource_requirement[name] = int(rec['values']['resource_requirement'])
    except Exception as e:
        raise ValueError(f'Invalid numeric value in record for {name}: {e}')
if set(item_names) != set(item_value.keys()) or set(item_names) != set(resource_requirement.keys()):
    raise ValueError('Mismatch in item identifiers between names, values, and requirements.')
m = gp.Model('BakeryOrder')
m.Params.MIPGap = 0.0001
x_vars = m.addVars(item_names, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((item_value[name] * x_vars[name] for name in item_names)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((resource_requirement[name] * x_vars[name] for name in item_names)) <= resource_capacity, name='storage_capacity')
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in x_vars.values():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')